/* Mesma classificacao conservadora usada no Disparo A (n8n-workflow-pos-consulta-iniciar.json) e no workflow legado de pos-consulta (producao): so 'sucesso' com key.id explicito confirma o envio de fato. D4 (quarta revisao): sem isso, a segunda entrega seria confirmada so por 'o node anterior nao lancou excecao', o que e mais fraco do que a garantia real da correcao C1 exige. E2 (quinta revisao): 'Chamar Iris Nova' NAO executa nos fallbacks de audio (fora do limite de 5min/15MB, ou falha/texto vazio na transcricao) -- 'Fallback: pedir reenvio' vai direto pra 'Enviar resposta Evolution' sem passar por 'Chamar Iris Nova'. Ler esse node sem checar isExecuted antes lanca excecao no n8n e quebra o envio do fallback. Mesmo padrao de guarda (isExecuted) ja usado pelo proprio node 'Enviar resposta Evolution' para instanceName/remoteJid. */
const chamouIrisNova = $('Chamar Iris Nova').isExecuted;
const respostaIrisNova = chamouIrisNova ? $('Chamar Iris Nova').first().json : null;
const resp = $json;
let confirmado = false, motivo = null;
if (resp && resp.success === true && resp.data && resp.data.key && resp.data.key.id) {
  confirmado = true;
} else if (resp && resp.error !== undefined) {
  motivo = String(resp.error).slice(0, 300);
} else {
  motivo = 'resposta_sem_key_id_sem_erro_explicito';
}
return { json: { pos_consulta_confirmacao: respostaIrisNova ? respostaIrisNova.pos_consulta_confirmacao : undefined, envio_confirmado: confirmado, motivo_evolution: motivo } };
